 pairs(c.expected)do\\010        local actual=u:getDrawArgumentValue(index)\\010        if actual~=actual or math.abs(actual-value)>0.000001 then return false end\\010    end\\010    return true\\010end\\010function s.fail(reason)\\010    if s.phase=='failed' or s.phase=='complete' then return end\\010    s.phase='failed';flag('DCSR_RELEASE_PENDING',0)\\010    local u=lead();if u then u:destroy()end\\010    if s.held then flag('DCSR_RELEASE_CLEANUP',1)end\\010    emit('FAILED,'..tostring(reason));notice('FAILED: '..tostring(reason)..'. Exit normally and retain logs.')\\010end\\010function s.cleaned()s.held=false;emit('HOLD_CLEANED')end\\010function s.arm(session,generation)\\010    if s.phase~='preparing' and s.phase~='waiting' then return false end\\010    local u=lead()\\010    if not u or not initial(u) or type(session)~='string' or not session:match('^[%w_]+$') or\\010        type(generation)~='number' or generation<1 then return false end\\010    s.session,s.generation=session,generation\\010    if s.phase~='waiting' then\\010        s.phase='waiting';emit('READY,'..session..','..generation)\\010        notice('Ready. Inspect the held lead, then F10 > DCS Recorder release test > Start playback. Do not toggle Active Pause.')\\010    end\\010    return true\\010end\\010function s.released(session,generation)\\010    if s.phase~='requested' or s.session~=session or s.generation~=generation then\\010        s.fail('unexpected_release_ack');return false\\010    end\\010    s.held=false;flag('DCSR_RELEASE_PENDING',0)\\010    s.phase='starting';s.release_time=timer.getTime()\\010    emit(string.format('PLAYER_RELEASED,%s,%d,%.9f',session,generation,s.release_time))\\010    notice('Released. Watch first movement and smoke, then let the short recording finish.')\\010    return true\\010end\\010local function sample(name)\\010    local u=Unit.getByName(name);if not u or not u:isExist() then return end\\010    local p,v=u:getPosition(),u:getVelocity();local values={}\\010